window.__finlexDocLoaded(10016,{"id":10016,"articles":[{"id":1000029,"no":"Overview","heading":"Scope & Key Requirements (Public Summary)","text":"Deals with the auditor's responsibilities relating to fraud in an audit of financial statements, including reinforced professional skepticism, fraud risk identification, and transparent communication (Revised July 2025).","seq":0},{"id":1000030,"no":"ISA 240 (Rev. 2025)","heading":"Fraud Responsibilities, Presumed Risks & 2025 Revision Highlights","text":"• Fraud triangle & skepticism (ISA 240.12–16): maintain heightened professional skepticism throughout; hold mandatory engagement team discussion on fraud susceptibility.\n• Two presumed fraud risks (ISA 240.27, 32): (1) improper revenue recognition (rebuttable, must document if rebutted); (2) management override of controls (NEVER rebuttable — mandatory journal entry testing, retrospective review of estimates, and evaluation of significant unusual transactions).\n• July 2025 Revised Edition highlights: clarifies auditor's role on fraud, reinforces fraud-lens risk assessment aligned with ISA 315, strengthens responses when fraud or suspected fraud is identified, and enhances transparency in auditor's reports (converged with China CSA 1141).","seq":1},{"id":1000031,"no":"Official Access","heading":"Official Handbook & Reference Entry","text":"Official source (IAASB 2026 Handbook): https://www.iaasb.org/publications/2026-handbook-international-quality-management-auditing-review-sustainability-and-other-assurance\nStatus: in_force. Detailed paragraph-level summaries and practice notes can be expanded incrementally.\n2026 Handbook Volume: Volume 1 (ISQM 1–2, ISA 200–720)\nLocal Private Full-Text Import: Place the free official 2026 IAASB Handbook PDF in local_pdfs/ and run `python3 scripts/import_private_intl_pdfs.py`.","seq":2}]});
